// How a pixel shader reads its textures, from its disassembly (materials/shader_texture_use.hpp).
#include "test_support.hpp"
#include "materials/shader_texture_use.hpp"

using namespace na::materials;

int main()
{
    return test::run({
        {"plain sampling is safe for a larger map; texel loads, size queries and named levels are not", [] {
            const ShaderTextureUse use = ReadShaderTextureUse(
                "//\n// Generated by Microsoft (R) HLSL Shader Compiler\n//\n// Resource Bindings: t9 is only a comment here\n"
                "ps_5_0\n"
                "dcl_globalFlags refactoringAllowed\n"
                "dcl_constantbuffer CB0[4], immediateIndexed\n"
                "dcl_sampler s0, mode_default\n"
                "dcl_resource_texture2d (float,float,float,float) t0\n"
                "dcl_resource_texture2d (float,float,float,float) t1\n"
                "dcl_resource_texture2d (float,float,float,float) t2\n"
                "dcl_resource_texture2d (float,float,float,float) t3\n"
                "dcl_resource_texture2d (float,float,float,float) t4\n"
                "dcl_resource_texture2d (float,float,float,float) t12\n"
                "dcl_input_ps linear v1.xy\n"
                "dcl_output o0.xyzw\n"
                "dcl_temps 3\n"
                "sample_indexable(texture2d)(float,float,float,float) r0.xyzw, v1.xyxx, t0.xyzw, s0\r\n"
                "  sample_b_indexable(texture2d)(float,float,float,float) r1.xyzw, v1.xyxx, t0.xyzw, s0, l(-1.000000)\n"
                "sample_d_indexable(texture2d)(float,float,float,float) r1.xyzw, v1.xyxx, t12.xyzw, s0, r0.xyxx, r0.zwzz\n"
                "ld_indexable(texture2d)(float,float,float,float) r1.xyzw, r0.xyzw, t1.xyzw\n"
                "resinfo_indexable(texture2d)(float,float,float,float)_uint r2.xy, l(0), t2.xyzw\n"
                "sample_indexable(texture2d)(float,float,float,float) r2.xyzw, v1.xyxx, t2.xyzw, s0\n"
                "sample_l_indexable(texture2d)(float,float,float,float) r2.xyzw, v1.xyxx, t3.xyzw, s0, l(0.000000)\n"
                "sample_aoffimmi_indexable(1,0,0)(texture2d)(float,float,float,float) r2.xyzw, v1.xyxx, t4.xyzw, s0\n"
                "gather4_indexable(texture2d)(float,float,float,float) r2.xyzw, v1.xyxx, t4.xyzw, s0.x\n"
                "mul r0.xyzw, r0.xyzw, cb0[3].xyzw\n"
                "mov o0.xyzw, r0.xyzw\n"
                "ret\n"
                "// Approximately 12 instruction slots used\n");
            CHECK(use.known);
            CHECK(use.declared.count() == 6 && use.declared[12] && !use.declared[9]);
            CHECK(use.SafeForLarger(0) && use.SafeForLarger(12) && use.sampled_plainly[0] && use.sampled_plainly[12]);
            CHECK(!use.SafeForLarger(1) && std::string(use.WhyNot(1)) == "ld_indexable");
            CHECK(!use.SafeForLarger(2) && std::string(use.WhyNot(2)) == "resinfo_indexable"); // sampled too, still not safe
            CHECK(!use.SafeForLarger(3) && std::string(use.WhyNot(3)) == "sample_l_indexable");
            CHECK(!use.SafeForLarger(4) && std::string(use.WhyNot(4)) == "sample_aoffimmi_indexable"); // the first reason stays
            CHECK(use.others.size() == 4);
            CHECK(use.SafeForLarger(7) && use.WhyNot(7) == nullptr); // nothing reads it
            CHECK(!use.SafeForLarger(128));
        }},
        {"the shader model 4 spelling reads the same way", [] {
            const ShaderTextureUse use = ReadShaderTextureUse(
                "ps_4_0\n"
                "dcl_sampler s0, mode_default\n"
                "dcl_sampler s1, mode_comparison\n"
                "dcl_resource_texture2d (float,float,float,float) t0\n"
                "dcl_resource_texture2d (float,float,float,float) t1\n"
                "dcl_temps 1\n"
                "sample r0.xyzw, v1.xyxx, t0.xyzw, s0\n"
                "sample_c_lz r0.x, v1.xyxx, t1.xxxx, s1, v1.z\n"
                "sample_aoffimmi(0,1,0) r0.xyzw, v1.xyxx, t0.xyzw, s0\n"
                "ret\n");
            CHECK(use.known && !use.SafeForLarger(1) && std::string(use.WhyNot(1)) == "sample_c_lz");
            CHECK(!use.SafeForLarger(0) && std::string(use.WhyNot(0)) == "sample_aoffimmi");
        }},
        {"anything that is not a shader model 4 to 5.0 pixel shader listing is unknown, and nothing is safe", [] {
            for (const char* text : {"", "vs_5_0\nret\n", "ps_5_1\nret\n", "    ps_3_0\n    dcl_2d s0\n    texld r0, t0, s0\n", "DXBC garbage", "// only comments\n"}) {
                const ShaderTextureUse use = ReadShaderTextureUse(text);
                CHECK(!use.known && !use.SafeForLarger(0) && use.WhyNot(0) != nullptr);
            }
            // A slot number no D3D11 stage has, or a bracket that never closes: not trusted.
            CHECK(!ReadShaderTextureUse("ps_5_0\nsample_indexable(texture2d)(float,float,float,float) r0.xyzw, v1.xyxx, t300.xyzw, s0\n").known);
            CHECK(!ReadShaderTextureUse("ps_5_0\nsample_indexable(texture2d r0.xyzw, v1.xyxx, t0.xyzw, s0\n").known);
        }},
        {"words that only look like texture registers are not counted", [] {
            const ShaderTextureUse use = ReadShaderTextureUse(
                "ps_5_0\n"
                "dcl_resource_texture2d (float,float,float,float) t0\n"
                "dcl_function_table ft0 = {fb0}\n"
                "mov r0.x, vt0.x\n"
                "ld_indexable(texture2d)(float,float,float,float) r0, r0.xyzw, t5x\n"
                "ret\n");
            CHECK(use.known && use.others.empty() && use.declared.count() == 1);
        }},
    });
}
